pub const TOOL_SCREENSHOT: &str = r#"{"description": "Capture the whole virtual desktop (display=-1), one monitor, a window (window=<selector> or target={...}) or a region, without activating the window: no cursor movement, no focus change.\nReturns {ok, image{w,h,format,quality}, source{x,y,w,h}, scale, monitors, cursor{x,y}, formula, capture{...}, elements?}. source is SCREEN pixels; the returned image maps back with screen_x = source.x + round((img_x + 0.5) * source.w / image.w), the same for y - formula carries that verbatim, and scale is the long-edge clamp that produced the image.\nfmt defaults to png (lossless); jpeg needs an explicit fmt:\"jpeg\", and quality 1..100 applies to jpeg only. A minimized window returns window_minimized; a refused frame returns capture_unavailable. The blank-frame detector is full-frame only (max channel < 8), never partial or stale: capture.blank_check reports the measured max_channel and its verdict. capture.moved_during_capture flags a window that moved while it was captured, so the frame may mix two positions. elements:true adds the structured element block, whose elements_window names the hwnd it enumerated. For an illegible control, re-request the same window with a tight region and max_px:null (full-resolution crop).\nwarnings[{code,field,requested,applied}] appears only when the server altered a request: quality_clamped (outside 1..100) and quality_ignored (quality sent with png).\\nforegroundUnchanged/cursorUnchanged report the measured before/after invariant; the pointer is never in the pixels - neither capture backend composites it; `cursor{x,y}` is a position report.\\nprivacyMasks:[{rect:[l,t,r,b]}|{window:<selector>}] blank the requested screen regions on the RGB pixels before resize and encode; masks[] names each one with rect in final image pixels, screenRect in screen pixels and the resolved window identity where used. A mask that matches nothing, a bad shape or an unresolvable window is a typed error. foregroundUnchanged, cursorUnchanged, clipboardUnchanged and noSteal are reported on every exit, including a typed timeout or other failure.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "display": {"type": "integer", "default": -1}, "region": {"anyOf": [{"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}, {"type": "null"}], "default": null}, "window": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "max_px": {"anyOf": [{"type": "integer", "minimum": 1, "maximum": 8192}, {"type": "null"}], "default": 1280}, "fmt": {"type": "string", "enum": ["png", "jpeg", "jpg"], "default": "png"}, "quality": {"type": "integer", "minimum": 1, "maximum": 100, "default": 80}, "grid": {"type": "boolean", "default": false}, "allow_crop_fallback": {"type": "boolean", "default": false}, "elements": {"type": "boolean", "default": false}, "out": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "privacyMasks": {"type": "array", "items": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"rect": {"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}}}, {"type": "object", "additionalProperties": false, "properties": {"window": {"anyOf": [{"type": "string"}, {"type": "object"}]}}}]}, "default": []}}}, "name": "screenshot", "outputSchema": {"type": "object", "properties": {"image": {"type": "object"}, "source": {"type": "object"}, "scale": {"type": "number"}, "monitors": {"type": "object"}, "cursor": {"type": "object"}, "window": {"type": "object"}, "capture": {"type": "object"}, "formula": {"type": "string"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "noSteal": {"type": "object"}, "clipboardUnchanged": {"type": "boolean"}, "masks": {"type": "array"}, "warnings": {"type": "array"}}, "required": ["image", "source", "scale", "monitors", "cursor", "capture", "formula"], "additionalProperties": true}, "title": "Screenshot", "annotations": {"title": "Screenshot", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_DIFF: &str = r#"{"description": "Pixel diff: which pixels moved between captures. base/next is {path:\"<png>\"} or a capture target ({target|window,display,region} as in screenshot, native, side-effect-free). A bare string operand is a window-title selector (case-insensitive substring), exactly like desktop_window's target string, NOT a file: use {\"path\":\"<absolute png>\"} for a file operand, and a bare path-like string is refused by the runtime as target_gone naming titleContains. Same dimensions or a typed size_mismatch names both. threshold (0-255, default 0) is the only tolerance; max_px (default 1280) clamps the returned image's long edge; out writes it to an absolute path; bbox toggles the union box. mask (native pixels, [[l,t,r,b],...] half-open) excludes regions from changed, total, ratio and bbox and reports masked_px; overlapping rects union, a rect outside the frame is bad_region.\nReturns {changed,total,ratio,bbox,identical,base,next,threshold,masked_px,bbox_space,image?,scale?,base_source?,next_source?,diff_out?}: changed,total,bbox are NATIVE operand pixels (bbox_space:\"native\"); image{w,h,format,quality}+scale describe the returned bytes, absent when none return; box->image: img_x = floor(bbox.x*scale); live operand: screen_x = base_source.x + bbox.x; a {path} operand reports base_source null. A changed diff adds the diff image: red over dimmed grey base. Each live capture operand also accepts privacyMasks:[{rect:[l,t,r,b]}|{window:<selector>}] with the same grammar as screenshot; the fresh pixels are blanked before the diff. A {path} operand has no screen geometry and refuses privacyMasks with bad_mask. Read-only: no activation or input; errors never raise.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"base": {"anyOf": [{"type": "object"}, {"type": "string"}]}, "next": {"anyOf": [{"type": "object"}, {"type": "string"}]}, "threshold": {"type": "integer", "minimum": 0, "maximum": 255, "default": 0}, "max_px": {"anyOf": [{"type": "integer", "minimum": 1, "maximum": 8192}, {"type": "null"}], "default": 1280}, "out": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "bbox": {"type": "boolean", "default": true}, "mask": {"type": "array", "items": {"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}}}, "required": ["base", "next"]}, "name": "diff", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "changed": {"type": "integer"}, "total": {"type": "integer"}, "ratio": {"type": "number"}, "bbox": {"anyOf": [{"type": "array"}, {"type": "null"}]}, "identical": {"type": "boolean"}, "base": {"type": "object"}, "next": {"type": "object"}, "threshold": {"type": "integer"}, "diff_out": {"anyOf": [{"type": "object"}, {"type": "null"}]}, "bbox_space": {"type": "string"}, "image": {"type": "object"}, "scale": {"type": "number"}, "base_source": {"type": ["object", "null"]}, "next_source": {"type": ["object", "null"]}, "warnings": {"type": "array"}, "masked_px": {"type": "integer"}}, "required": ["ok", "changed", "total", "ratio", "identical", "base", "next"], "additionalProperties": true}, "title": "Diff", "annotations": {"title": "Diff", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_LIST_WINDOWS: &str = r#"{"description": "List visible top-level windows as JSON:\n[{hwnd,pid,exe,title,class,rect:[l,t,r,b],dwm_rect,client_rect,\nminimized,maximized,foreground,cloaked,visible,dpi}].\nrect=GetWindowRect (compat, includes the invisible border);\ndwm_rect=DWMWA_EXTENDED_FRAME_BOUNDS (mapping truth, else rect with\ndwm_fallback:true); client_rect in screen space. Read-only: no focus\nchange, no window is touched.\nelevated names the target's integrity: true when its process runs\nelevated (input from this unelevated server is UIPI-blocked: refused\nbefore injecting with uipi_blocked, flagged blocked_by_uipi:true),\nfalse when not elevated, null when unreadable (never named elevated).\ninclude_app_ids (default false) adds appId per window from the window's\nAppUserModelID property store (a string, or null when the store/property is\nunavailable). It is opt-in because that read is a per-window COM call.", "inputSchema": {"properties": {"include_app_ids": {"type": "boolean", "default": false}}, "type": "object", "additionalProperties": false}, "name": "list_windows", "outputSchema": {"type": "object", "properties": {"windows": {"type": "array", "items": {"type": "object"}}}, "required": ["windows"], "additionalProperties": true}, "title": "List Windows", "annotations": {"title": "List Windows", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_WINDOW: &str = r#"{"description": "Move, resize, minimize, restore, close, topmost, focus or maximize a window by selector, hwnd or target. move/resize/minimize/restore/close/topmost are always no-steal (SWP_NOACTIVATE / SW_SHOWMINNOACTIVE), never touch the owner's cursor, keyboard or clipboard, and IGNORE allow_foreground. allow_foreground is a permission for focus and maximize ONLY: without allow_foreground:true those two are refused no_foreground_policy (the refusal names the flag and the verb); with it focus calls SetForegroundWindow and maximize uses ShowWindow(SW_MAXIMIZE). move needs x,y; resize needs width,height; close posts WM_CLOSE.\nReturns {ok, action, hwnd} plus the verb's fields and measured foregroundBefore/foregroundAfter/foregroundChanged with truthful foregroundUnchanged/cursorUnchanged; a working focus reports foregroundChanged:true, and a refusal reports foregroundBefore == foregroundAfter. An ambiguous or vanished target is typed (ambiguous_target / target_gone) and never falls back to the foreground window. Read-only listing, capture and element walks are list_windows, screenshot and elements.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"action": {"type": "string", "enum": ["focus", "move", "resize", "minimize", "maximize", "restore", "close", "topmost"]}, "title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "x": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "y": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "width": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "height": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "allow_foreground": {"type": "boolean", "default": false, "description": "Permission for focus and maximize ONLY: focus calls SetForegroundWindow and maximize uses ShowWindow(SW_MAXIMIZE). Without allow_foreground:true those two are refused no_foreground_policy; move/resize/minimize/restore/close/topmost ignore this flag entirely and are always no-steal."}}, "required": ["action"]}, "name": "window", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "action": {"type": "string"}, "hwnd": {"type": "integer"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "width": {"type": "integer"}, "height": {"type": "integer"}, "error": {"type": "string"}, "candidates": {"type": "array"}, "code": {"type": "string"}, "foregroundBefore": {"anyOf": [{"type": "integer"}, {"type": "null"}]}, "foregroundAfter": {"anyOf": [{"type": "integer"}, {"type": "null"}]}, "foregroundChanged": {"type": "boolean"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "target_locked": {"type": "integer"}}, "required": ["ok"], "additionalProperties": true}, "title": "Window", "annotations": {"title": "Window", "readOnlyHint": false, "destructiveHint": true, "idempotentHint": false, "openWorldHint": false}}"#;
pub const TOOL_DO: &str = r#"{"description": "BURST tool: one call runs an ordered actions[] batch against one window.\ntarget={hwnd?,pid?,exe?,appId?,titleContains?,className?} (or a selector string) locks ONE top-level window for the whole call and is revalidated before every action; the legacy background selector is an alternative lock and target wins when both are given. Without a target every acting verb is refused before anything is sent (target_required for keys and patterns, no_cursor_policy for pointer acts), and nothing ever falls back to the foreground window.\nDelivery (default): click/down/up/drag/scroll/type/key/hotkey post window messages to the locked target; click, scroll and invoke with an element prefer the control UIA pattern (Invoke, SelectionItem, Toggle, ExpandCollapse, ScrollPattern), and click falls back to a posted button message at the element centre whose readable state is read before and after; wait, wait_for and clipboard_get deliver nothing. move is refused with no_cursor_policy and focus_window with no_foreground_policy. Real input is OPT-IN at top level, never implicit: allow_cursor:true delivers move and coordinate pointer verbs through SetCursorPos/SendInput after a WindowFromPoint root-owner guard (a point outside the locked target, or on a different window, is refused point_not_target naming that window and delivers nothing); no cursor action calls SetForegroundWindow. cursor_restore:true (the default) puts the entry pointer back after the last action, including a partial or failed burst; the reply reports cursorRestored (true|false|null), cursorMoved and cursorUnchanged. allow_foreground:true makes focus_window call SetForegroundWindow on the locked target and no other verb take focus; focus_guard:true restores the entry foreground when possible and reports foregroundRestored. delivery:\"sendinput\" stays refused - opt in at the top level. clipboard_set writes real CF_UNICODETEXT only when the top-level do call sets allow_clipboard:true; without it the call is refused with no_clipboard_policy before the clipboard is opened. restore_clipboard:true snapshots the previous clipboard text before the first write and restores it after the last action, including a partial or failed burst; the clipboard object reports {writes, restores, previous (empty|text|non_text), bytes}. One policy, two scopes for UIA text entry: ValuePattern.SetValue may focus its control, so set_value and type with an element are refused with background_unavailable on the owner's desktop whatever the flags; desktop:\"hidden\" creates a private desktop with no owner to steal focus from, so both are allowed there through the UIA pattern with the readback effect. expect_fp is required for these on the owner's desktop and not on the hidden one, which has no advance elements snapshot.\nCoordinates: x/y under a target are CLIENT-area physical pixels; without a target they are virtual-desktop SCREEN pixels converted with ScreenToClient. With allow_cursor the client point is converted to screen, checked against the target rect and the window under it, and only then delivered as real pointer input. Posted coordinates are signed 16-bit: anything outside -32768..32767 is refused with bad_coordinates before a message is posted. move takes x/y or dx/dy, never both.\nEffects: every result carries delivered (uia|posted|cursor|foreground|none), via and effect. ok is true when the action was delivered and not disproven. UIA acts (invoke, an element click, toggle, select, expand/collapse, set_value and type on an element) read the control back: effect is verified when a readable state moved to the requested value, pattern-returned when the provider accepted the call but the control exposes no readable state, and unchanged (ok:false, background_unavailable) when a readable state did not move. A posted click whose readable control state did not change reports ok:false with background_unavailable and effect unchanged; a raw x/y click reports effect unverified.\nStale refs: every element mutation (invoke, set_value, click and type with an element) requires expect_fp, the fp from an elements entry, on the owner's desktop; on desktop:\"hidden\" the text-entry verbs resolve fresh because no elements snapshot exists before the call. Without it the call refuses expect_fp_required and the error carries the fresh fp; a mismatch refuses resolution:stale with a stale_ref error naming expected vs found fps. Retry with the returned fp. fp is identity, never state: rect, text and control state do not participate, so a matching fp means the same control, not the same condition; read effect for what the control then did. An ambiguous selector returns candidates {name,role,auto_id,rect,ref,fp} and acts on nothing; an explicit index picks the nth match.\nKeyboard: type posts WM_CHAR per unit; key and hotkey post WM_KEYDOWN/WM_SYSKEYDOWN and hold Shift when the layout requires it. chunk_chars/chunk_ms are accepted for compatibility and perform no pacing. scroll axis v|h selects the wheel; drag is down/move/up at exact points; hover:true is the only way to post a WM_MOUSEMOVE.\nBudget: at most 256 actions and 300 ms of total elapsed time per call; exceeding either is a typed burst_budget_exceeded result naming the limit and the actual value, and the remaining actions do not run. An element wait reports satisfied_by {selector, fp, path} naming the control that satisfied it (null when nothing did) and fp_matched when expect_fp was supplied; a mismatch is a report, never an error. Top-level ok is true only when EVERY action succeeded; a wait_for timeout is never an error. settle_ms is one trailing pause after the last action. focus_guard:true restores the entry foreground window when an allow_foreground focus changed it, and focus_before/focus_after are always reported.\ndry_run=true validates exactly like the live call (every policy refusal included) but posts nothing, and invoke under dry_run still reports found|not-found|ambiguous. desktop:\"hidden\" launches the program named by background on a private desktop (background_args are its argv) and returns the burst JSON plus hidden_desktop{...}; the owner's cursor, foreground and focus are never touched. a dry run delivers nothing: every result reports delivered:\"none\", posted:0 and effect:\"none\".", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"actions": {"type": "array", "minItems": 1, "maxItems": 256, "items": {"oneOf": [{"type": "object", "properties": {"type": {"const": "move"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "dx": {"type": "integer"}, "dy": {"type": "integer"}, "relative": {"type": "boolean"}}, "required": ["type"], "anyOf": [{"required": ["x", "y"]}, {"required": ["dx", "dy"]}]}, {"type": "object", "properties": {"type": {"const": "click"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "button": {"type": "string"}, "count": {"type": "integer"}, "hover": {"type": "boolean", "default": false}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "down"}, "button": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "up"}, "button": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "drag"}, "from": {"type": "array", "items": {"type": "integer"}, "minItems": 2, "maxItems": 2}, "to": {"type": "array", "items": {"type": "integer"}, "minItems": 2, "maxItems": 2}, "button": {"type": "string"}}, "required": ["type", "from", "to"]}, {"type": "object", "properties": {"type": {"const": "scroll"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "amount": {"type": "integer"}, "axis": {"type": "string", "enum": ["v", "h"], "default": "v"}, "element": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "type"}, "text": {"type": "string"}, "chunk_chars": {"type": "integer"}, "chunk_ms": {"type": "integer"}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "key"}, "name": {"type": "string"}, "hold_ms": {"type": "integer", "minimum": 0, "maximum": 60000}, "repeat": {"type": "integer", "minimum": 1, "maximum": 100}, "gap_ms": {"type": "integer", "minimum": 0, "maximum": 60000}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "hotkey"}, "keys": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "string"}]}}, "required": ["type", "keys"]}, {"type": "object", "properties": {"type": {"const": "wait"}, "ms": {"type": "integer"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "wait_for"}, "kind": {"type": "string", "enum": ["window_appear", "window_disappear", "pixel", "stable", "element"]}, "selector": {"type": "string"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "color": {"type": "array", "items": {"type": "integer"}, "minItems": 3, "maxItems": 3}, "tolerance": {"type": "integer"}, "region": {"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}, "timeout_ms": {"type": "integer"}, "poll_ms": {"type": "integer"}, "window": {"type": "string"}, "element": {"type": "string"}, "expect_fp": {"type": "string", "description": "Reported as fp_matched; never turns the wait into an error"}, "state": {"type": "string", "enum": ["appear", "disappear", "enabled", "disabled"], "default": "appear"}}, "required": ["type", "kind"]}, {"type": "object", "properties": {"type": {"const": "focus_window"}, "title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "invoke"}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}, "state": {"type": "string", "enum": ["expand", "collapse"]}}, "required": ["type", "element"]}, {"type": "object", "properties": {"type": {"const": "set_value"}, "element": {"type": "string"}, "text": {"type": "string"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type", "element", "text"]}, {"type": "object", "properties": {"type": {"const": "clipboard_set"}, "text": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "clipboard_get"}}, "required": ["type"]}]}}, "background": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "background_args": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "default": null}, "focus_guard": {"type": "boolean", "default": false}, "settle_ms": {"type": "integer", "default": 0}, "dry_run": {"type": "boolean", "default": false}, "desktop": {"anyOf": [{"type": "string", "enum": ["hidden"]}, {"type": "null"}], "default": null}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "allow_foreground": {"type": "boolean", "default": false, "description": "Opt in to ONE explicit focus act: focus_window calls SetForegroundWindow on the locked target. No other verb takes focus; without this flag focus_window is refused no_foreground_policy."}, "allow_cursor": {"type": "boolean", "default": false, "description": "Opt in to real pointer input for move and coordinate click/down/up/drag/scroll with a locked target: SetCursorPos/SendInput after a WindowFromPoint root-owner guard (point_not_target names another window and delivers nothing). Never calls SetForegroundWindow; without it the old posted/refused path is unchanged."}, "allow_clipboard": {"type": "boolean", "default": false, "description": "Opt in to a real CF_UNICODETEXT write to the owner's global clipboard. Without it clipboard_set is refused with no_clipboard_policy before OpenClipboard; reads (clipboard_get) never need it. Use restore_clipboard:true to put the previous text back after the burst."}, "restore_clipboard": {"type": "boolean", "default": false, "description": "Snapshot the previous clipboard text before the first write and restore it after the last action, even on a partial or failed burst. Empty or non-text content is cleared on restore because it cannot be copied back. Reported as clipboard.{writes,restores,previous,bytes}."}, "cursor_restore": {"type": "boolean", "default": true, "description": "Restore the entry pointer after the last action of an allow_cursor burst, including a partial or failed one. false leaves the pointer where the real input put it. Reported as cursorRestored (true|false|null) alongside cursorMoved and cursorUnchanged."}}, "required": ["actions"]}, "name": "do", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "failed": {"type": "integer"}, "results": {"type": "array"}, "total_ms": {"type": "number"}, "sendinput_calls": {"type": "integer"}, "sendinput_ms": {"type": "number"}, "events": {"type": "integer"}, "focus_before": {"type": "integer"}, "focus_after": {"type": "integer"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "cursorMoved": {"type": "boolean"}, "cursorRestored": [{"type": "boolean"}, {"type": "null"}], "foregroundRestored": [{"type": "boolean"}, {"type": "null"}], "clipboard": {"type": "object"}, "target_locked": {"type": "integer"}, "target_pid": {"type": "integer"}, "target_exe": {"type": "string"}}, "required": ["results", "total_ms", "sendinput_calls", "sendinput_ms", "events", "focus_before", "focus_after"], "additionalProperties": true}, "title": "Do", "annotations": {"title": "Do", "readOnlyHint": false, "destructiveHint": true, "idempotentHint": false, "openWorldHint": false}}"#;
pub const TOOL_CURSOR: &str = r#"{"description": "Current cursor position + monitor rects as JSON:\n{x, y, screens:[[l,t,r,b],...]}.", "inputSchema": {"properties": {}, "type": "object", "additionalProperties": false}, "name": "cursor", "outputSchema": {"type": "object", "properties": {"x": {"type": "integer"}, "y": {"type": "integer"}, "screens": {"type": "array"}}, "required": ["x", "y", "screens"], "additionalProperties": true}, "title": "Cursor", "annotations": {"title": "Cursor", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_ELEMENTS: &str = r#"{"description": "List structured UI elements for a window as JSON, zero-pixel (no screenshot, no focus change, no input).\nTarget by selector (title text or hwnd; the same TargetLock as target:). detail=true keeps the raw win and hwnd fields on each entry and adds text (TextPattern document text, capped at 4000 chars) plus text_truncated; the default false returns the compact {ref,role,name,auto_id,rect,offscreen,invokable,path,fp}.\nEach entry carries fp, a stable identity fingerprint (FNV-1a over role/name/auto_id/invokable, 16 hex chars); pass it as expect_fp to invoke, set_value, click and type on an element: a call without one is refused with the fresh fp, and a mismatched one refuses stale_ref instead of acting on the wrong control. fp is identity, never state: rect, text and control state (checked, selected, expanded, range) do not participate, so an fp match means the same control, not the same condition; a state-sensitive action needs a readback (effect), never a fingerprint. offscreen:true marks a control with no area: the rect is kept for shape stability but click refuses it with offscreen_element.\nReturns {backend,truncated,rect_space,elements,uia_available,uia_error,fallback,empty[,empty_reason],depth_capped,depth_limit}; rect_space is screen. max_depth (1..32, default 8) bounds the UIA walk; offset pages past the 200-entry cap and next_offset carries the next page or null. When UIA is unavailable the Win32 child enumeration serves the entries.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "detail": {"type": "boolean", "default": false}, "max_depth": {"type": "integer", "minimum": 1, "maximum": 32, "default": 8}, "offset": {"type": "integer", "minimum": 0, "default": 0}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}}}, "name": "elements", "outputSchema": {"type": "object", "properties": {"backend": {"type": "string"}, "truncated": {"type": "boolean"}, "rect_space": {"type": "string"}, "elements": {"type": "array"}, "uia_available": {"type": "boolean"}, "uia_error": {}, "fallback": {}, "empty": {"type": "boolean"}, "empty_reason": {"type": "string"}, "depth_capped": {"type": "boolean"}, "depth_limit": {"type": "integer"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "noSteal": {"type": "object"}}, "required": ["backend", "truncated", "rect_space", "elements", "uia_available", "empty", "depth_capped", "depth_limit"], "additionalProperties": true}, "title": "Elements", "annotations": {"title": "Elements", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;

/// hand's desktop recording tool: one targeted window, paced to fps, in a
/// shared MJPEG AVI container. The description is the agent-facing contract:
/// caps, no-steal behaviour and partial-file reporting are all load-bearing.
pub const TOOL_RECORD: &str = r#"{"description": "Record ONE targeted window to a playable MJPEG AVI file, without ever activating the window, moving the pointer or touching the clipboard. target is required: an object {hwnd?,pid?,exe?,appId?,titleContains?,className?} or a selector string; it resolves one top-level window and is revalidated before every frame, with no fallback to the foreground window. Each frame is the screenshot window capture path encoded as JPEG: fmt=jpeg, quality clamped to 1..100 (default 75), long edge clamped by max_px to 160..1280 (default 960). duration_ms is clamped to 250..15000 (default 3000) and fps to 1..15 (default 8); Slots that overrun are dropped and, once a frame exists, the previous JPEG is written again so the constant-rate AVI keeps the requested duration; each dropped slot is counted in droppedFrames and capturedFrames counts only fresh captures, while frames counts every chunk in the file. If the very first slot overruns there is no frame to repeat, so it is counted without padding. out is required: an absolute .avi path whose parent directory already exists and whose file does not exist; a pre-existing, relative or wrong-extension path is refused as typed invalid_args before any capture. Returns {ok,path,bytes,frames,capturedFrames,durationMs,fps,width,height,container:'mjpeg-avi',firstFrameTsMs,lastFrameTsMs,droppedFrames,foregroundUnchanged,cursorUnchanged,clipboardUnchanged}; the three invariants are measured before/after like screenshot, and optional warnings[] names every clamp. If the target vanishes mid-recording the typed result names the frames already written and the partial AVI is kept; if no frame was captured the result is capture_unavailable with no path and no file is written. No upload, no default recording.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string", "minLength": 1}]}, "duration_ms": {"type": "integer", "minimum": 250, "maximum": 15000, "default": 3000}, "fps": {"type": "integer", "minimum": 1, "maximum": 15, "default": 8}, "max_px": {"type": "integer", "minimum": 160, "maximum": 1280, "default": 960}, "quality": {"type": "integer", "minimum": 1, "maximum": 100, "default": 75}, "out": {"type": "string", "minLength": 1}}, "required": ["target", "out"]}, "outputSchema": {"type": "object", "additionalProperties": false, "properties": {"ok": {"type": "boolean"}, "path": {"type": "string"}, "bytes": {"type": "integer", "minimum": 0}, "frames": {"type": "integer", "minimum": 0}, "capturedFrames": {"type": "integer", "minimum": 0}, "durationMs": {"type": "integer"}, "fps": {"type": "integer"}, "width": {"type": "integer"}, "height": {"type": "integer"}, "container": {"const": "mjpeg-avi"}, "firstFrameTsMs": {"type": "integer", "minimum": 0}, "lastFrameTsMs": {"type": "integer", "minimum": 0}, "droppedFrames": {"type": "integer", "minimum": 0}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "clipboardUnchanged": {"type": "boolean"}, "warnings": {"type": "array", "items": {"type": "object"}}, "noSteal": {"type": "object"}, "code": {"type": "string"}, "error": {"type": "string"}, "framesWritten": {"type": "integer", "minimum": 0}, "reason": {"type": "string"}, "field": {"type": "string"}, "tool": {"type": "string"}, "candidates": {"type": "array", "items": {"type": "object"}}}, "required": ["ok"]}, "name": "record", "title": "Desktop window recording", "annotations": {"readOnlyHint": false, "destructiveHint": false, "idempotentHint": false, "openWorldHint": false}}"#;

#[cfg(test)]
mod tests {
    use super::*;

    /// The published tool schema is the only way a model learns that the
    /// pointer restore is on by default and can be opted out of.
    #[test]
    fn do_schema_declares_cursor_restore_with_default_true() {
        let tool: serde_json::Value = serde_json::from_str(TOOL_DO).expect("TOOL_DO is valid JSON");
        let props = tool["inputSchema"]["properties"]
            .as_object()
            .expect("inputSchema.properties");
        let cr = props
            .get("cursor_restore")
            .expect("desktop_do must publish cursor_restore");
        assert_eq!(cr["type"], serde_json::Value::from("boolean"), "{cr}");
        assert_eq!(cr["default"], serde_json::Value::from(true), "{cr}");
        let desc = cr["description"].as_str().unwrap_or("");
        assert!(desc.contains("allow_cursor"), "{cr}");
        assert!(desc.contains("cursorRestored"), "{cr}");
    }

    /// The output contract must name the three measured foreground fields the
    /// implementation now emits on every reply, and the refusal invariant.
    #[test]
    fn window_schema_publishes_foreground_trio_and_refusal_contract() {
        let tool: serde_json::Value =
            serde_json::from_str(TOOL_WINDOW).expect("TOOL_WINDOW is valid JSON");
        let out = &tool["outputSchema"];
        assert_eq!(out["additionalProperties"], serde_json::Value::from(true));
        let props = out["properties"]
            .as_object()
            .expect("outputSchema.properties");
        for name in [
            "ok",
            "action",
            "hwnd",
            "x",
            "y",
            "width",
            "height",
            "error",
            "candidates",
            "code",
            "foregroundUnchanged",
            "cursorUnchanged",
            "target_locked",
            "foregroundBefore",
            "foregroundAfter",
            "foregroundChanged",
        ] {
            assert!(
                props.contains_key(name),
                "window outputSchema missing {name}"
            );
        }
        for name in ["foregroundBefore", "foregroundAfter"] {
            let variants = props[name]["anyOf"].as_array().expect("anyOf for {name}");
            let kinds: Vec<&str> = variants
                .iter()
                .map(|v| v["type"].as_str().unwrap_or(""))
                .collect();
            assert_eq!(kinds, vec!["integer", "null"], "{name}");
        }
        assert_eq!(
            props["foregroundChanged"]["type"],
            serde_json::Value::from("boolean")
        );
        let desc = tool["description"].as_str().expect("description");
        assert!(desc.contains("foregroundBefore/foregroundAfter/foregroundChanged"));
        assert!(desc.contains("a working focus reports foregroundChanged:true"));
        assert!(desc.contains("a refusal reports foregroundBefore == foregroundAfter"));
    }

    /// A bare string diff operand is a title selector at runtime (resolve_operand
    /// routes it through ShotArgs.window); the published description must say so
    /// rather than implying that a path-like string is read as a file.
    #[test]
    fn diff_schema_documents_bare_string_as_title_selector() {
        let tool: serde_json::Value =
            serde_json::from_str(TOOL_DIFF).expect("TOOL_DIFF is valid JSON");
        let props = tool["inputSchema"]["properties"]
            .as_object()
            .expect("inputSchema.properties");
        for name in ["base", "next"] {
            let variants = props[name]["anyOf"].as_array().expect("anyOf for {name}");
            let kinds: Vec<&str> = variants
                .iter()
                .map(|v| v["type"].as_str().unwrap_or(""))
                .collect();
            assert_eq!(kinds, vec!["object", "string"], "{name} input surface");
        }
        let desc = tool["description"].as_str().expect("description");
        assert!(desc.contains("A bare string operand is a window-title selector"));
        assert!(desc.contains("case-insensitive substring"));
        assert!(desc.contains("desktop_window's target string"));
        assert!(desc.contains("<absolute png>"));
        assert!(desc.contains("target_gone"));
        assert!(desc.contains("titleContains"));
    }
}
